"""Temporal reconstruction of daily gridded climate datasets."""

from __future__ import annotations

import datetime
import math
import re
from typing import Any

_SCHEMA = "climate-grid/temporal-v1"
_DATASET_SCHEMA = "climate-grid/dataset-v1"
_IDW_SCHEMA = "climate-grid/idw-v1"
_FRAME_KEYS = frozenset({"time", "dataset"})
_DATASET_KEYS = frozenset({"schema", "data"})
_GRID_KEYS = frozenset({"schema", "lats", "lons", "values", "counts"})
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _round_output(value: float) -> float:
    value = round(value, 12)
    if value == 0.0:
        # Normalize negative zero.
        return 0.0
    return value


def _parse_date(value: Any, where: str) -> datetime.date:
    if not isinstance(value, str):
        raise TypeError(f"{where}.time must be a str")
    if _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{where}.time must be a YYYY-MM-DD date")
    year, month, day = (int(part) for part in value.split("-"))
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"{where}.time must be a valid Gregorian date") from None


def _validate_axis(axis: Any, name: str) -> None:
    if not isinstance(axis, list):
        raise TypeError(f"{name} must be a list")
    if len(axis) == 0:
        raise ValueError(f"{name} must be non-empty")
    for index, value in enumerate(axis):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError(
                f"{name}[{index}] must be a finite non-bool int or float"
            )
        if not math.isfinite(value):
            raise ValueError(f"{name}[{index}] must be finite")
    for index in range(1, len(axis)):
        if axis[index] <= axis[index - 1]:
            raise ValueError(f"{name} must be strictly increasing")


def _validate_matrix(
    matrix: Any, n_lat: int, n_lon: int, name: str, *, counts: bool
) -> None:
    if not isinstance(matrix, list):
        raise TypeError(f"{name} must be a list")
    if len(matrix) != n_lat:
        raise ValueError(f"{name} must have {n_lat} rows (one per lat)")

    for row_index, row in enumerate(matrix):
        where = f"{name}[{row_index}]"
        if not isinstance(row, list):
            raise TypeError(f"{where} must be a list")
        if len(row) != n_lon:
            raise ValueError(f"{where} must have {n_lon} cells (one per lon)")

        for cell_index, cell in enumerate(row):
            target = f"{where}[{cell_index}]"
            if counts:
                if not isinstance(cell, int) or isinstance(cell, bool):
                    raise TypeError(f"{target} must be a non-bool int")
                if cell < 0:
                    raise ValueError(f"{target} must be non-negative")
            elif cell is not None:
                if not isinstance(cell, (int, float)) or isinstance(cell, bool):
                    raise TypeError(f"{target} must be a number or None")
                if not math.isfinite(cell):
                    raise ValueError(f"{target} must be finite")


def _validate_grid(grid: Any, where: str) -> tuple[list, list, list]:
    if not isinstance(grid, dict):
        raise TypeError(f"{where} must be a dict")
    if set(grid.keys()) != _GRID_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, lats, lons, values, counts"
        )
    if not isinstance(grid["schema"], str):
        raise TypeError(f"{where}.schema must be a str")
    if grid["schema"] != _IDW_SCHEMA:
        raise ValueError(f"{where}.schema must be {_IDW_SCHEMA!r}")

    lats = grid["lats"]
    lons = grid["lons"]
    _validate_axis(lats, f"{where}.lats")
    _validate_axis(lons, f"{where}.lons")

    _validate_matrix(
        grid["values"], len(lats), len(lons), f"{where}.values", counts=False
    )
    _validate_matrix(
        grid["counts"], len(lats), len(lons), f"{where}.counts", counts=True
    )

    return lats, lons, grid["values"]


def _validate_dataset(
    dataset: Any, frame_index: int
) -> tuple[list[str], dict[str, tuple[list, list, list]]]:
    where = f"frames[{frame_index}].dataset"
    if not isinstance(dataset, dict):
        raise TypeError(f"{where} must be a dict")
    if set(dataset.keys()) != _DATASET_KEYS:
        raise ValueError(f"{where} must have exactly the keys schema, data")
    if not isinstance(dataset["schema"], str):
        raise TypeError(f"{where}.schema must be a str")
    if dataset["schema"] != _DATASET_SCHEMA:
        raise ValueError(f"{where}.schema must be {_DATASET_SCHEMA!r}")

    data = dataset["data"]
    if not isinstance(data, dict):
        raise TypeError(f"{where}.data must be a dict")
    if len(data) == 0:
        raise ValueError(f"{where}.data must be non-empty")

    order: list[str] = []
    grids: dict[str, tuple[list, list, list]] = {}
    for element, grid in data.items():
        if not isinstance(element, str):
            raise TypeError(f"{where}.data element names must be str")
        if element == "":
            raise ValueError(f"{where}.data element names must be non-empty")
        order.append(element)
        grids[element] = _validate_grid(grid, f"{where}.data[{element!r}]")

    ref_lats, ref_lons, _ = grids[order[0]]
    for element in order[1:]:
        lats, lons, _ = grids[element]
        if lats != ref_lats or lons != ref_lons:
            raise ValueError(
                f"lats/lons for element {element!r} must match within a frame"
            )

    return order, grids


def reconstruct(frames, *, max_gap: int = 2) -> dict:
    """Reconstruct a gap-filled daily time series of gridded datasets.

    Each frame is a dict with exactly the keys ``time`` and ``dataset``:
    ``time`` is a unique, strictly formatted Gregorian ``YYYY-MM-DD`` str and
    ``dataset`` is a complete :func:`climate_grid.dataset.build` result
    (schema ``climate-grid/dataset-v1``), whose per-element values are
    complete :func:`climate_grid.interpolation.idw_grid` results.  Frames may
    be given out of order, but every frame must contain the same elements in
    the same order, and each element's ``lats``/``lons`` must be identical
    within and across frames.

    The output time axis spans the earliest through the latest frame date,
    one entry per calendar day in ascending order; days without a frame are
    treated as all-``None``.  For every element and grid cell, known values
    are kept as ``observed``.  A consecutive run of missing values is
    ``interpolated`` by linear interpolation against calendar date only when
    known values bound the run on both sides and the distance in days between
    those bounding values is at most ``max_gap`` (a non-bool non-negative
    int); otherwise the run stays ``missing``, as do un-bounded runs at
    either end of the axis.

    The returned mapping uses the key order ``schema, times, lats, lons,
    data``; ``schema`` is ``climate-grid/temporal-v1`` and ``times`` is the
    list of ``YYYY-MM-DD`` strings.  ``data`` follows the first frame's
    element order and each item uses the key order ``values, status,
    uncertainty``; the three members are nested ``[time][lat][lon]``.
    Status is one of ``observed``, ``interpolated`` or ``missing``, and
    uncertainty is ``0.0`` for observed values, half the absolute difference
    of the two bounding values for interpolated values, and ``None`` for
    missing values.  Every output number (including known values and the
    shared ``lats``/``lons``) is ``round(x, 12)`` with negative zero
    normalized to ``0.0``.  Inputs are not modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for malformed dates, duplicate times, bad schemas or
    grids, empty frames, invalid ``max_gap``, or elements/axes that are not
    consistent within or across frames.
    """
    if not isinstance(frames, list):
        raise TypeError("frames must be a list of frame dicts")
    if len(frames) == 0:
        raise ValueError("frames must be non-empty")

    # (date, element order, {element: (lats, lons, values)}) per input frame.
    parsed: list[tuple[datetime.date, list[str], dict]] = []
    seen_dates: set[datetime.date] = set()
    for index, frame in enumerate(frames):
        where = f"frames[{index}]"
        if not isinstance(frame, dict):
            raise TypeError(f"{where} must be a dict")
        if set(frame.keys()) != _FRAME_KEYS:
            raise ValueError(f"{where} must have exactly the keys time, dataset")

        day = _parse_date(frame["time"], where)
        if day in seen_dates:
            raise ValueError(f"duplicate frame time: {frame['time']!r}")
        seen_dates.add(day)

        order, grids = _validate_dataset(frame["dataset"], index)
        parsed.append((day, order, grids))

    if not isinstance(max_gap, int) or isinstance(max_gap, bool):
        raise TypeError("max_gap must be a non-bool int")
    if max_gap < 0:
        raise ValueError("max_gap must be non-negative")

    reference_order = parsed[0][1]
    reference_grids = parsed[0][2]
    for _, order, grids in parsed[1:]:
        if order != reference_order:
            raise ValueError(
                "all frames must contain the same elements in the same order"
            )
        for element in reference_order:
            ref_lats, ref_lons, _ = reference_grids[element]
            lats, lons, _ = grids[element]
            if lats != ref_lats or lons != ref_lons:
                raise ValueError(
                    f"lats/lons for element {element!r} must match across frames"
                )

    ordered = sorted(parsed, key=lambda item: item[0])
    start = ordered[0][0]
    end = ordered[-1][0]
    n_times = (end - start).days + 1
    times = [
        (start + datetime.timedelta(days=offset)).isoformat()
        for offset in range(n_times)
    ]
    # (day offset from start, grids) for each present frame, ascending.
    present = [((day - start).days, grids) for day, _, grids in ordered]

    first_element = reference_order[0]
    out_lats = [
        _round_output(value) for value in reference_grids[first_element][0]
    ]
    out_lons = [
        _round_output(value) for value in reference_grids[first_element][1]
    ]

    data: dict[str, dict] = {}
    for element in reference_order:
        ref_lats, ref_lons, _ = reference_grids[element]
        n_lat = len(ref_lats)
        n_lon = len(ref_lons)
        values = [
            [[None for _ in range(n_lon)] for _ in range(n_lat)]
            for _ in range(n_times)
        ]
        status = [
            [[None for _ in range(n_lon)] for _ in range(n_lat)]
            for _ in range(n_times)
        ]
        uncertainty = [
            [[None for _ in range(n_lon)] for _ in range(n_lat)]
            for _ in range(n_times)
        ]

        for lat_index in range(n_lat):
            for lon_index in range(n_lon):
                # Known value per day offset; None means missing.
                series: list[float | None] = [None] * n_times
                for offset, grids in present:
                    value = grids[element][2][lat_index][lon_index]
                    if value is not None:
                        series[offset] = value

                tick = 0
                while tick < n_times:
                    if series[tick] is not None:
                        values[tick][lat_index][lon_index] = _round_output(
                            series[tick]
                        )
                        status[tick][lat_index][lon_index] = "observed"
                        uncertainty[tick][lat_index][lon_index] = 0.0
                        tick += 1
                        continue

                    # Run of consecutive missing values [tick, run_end).
                    run_end = tick
                    while run_end < n_times and series[run_end] is None:
                        run_end += 1
                    left = tick - 1
                    gap_days = run_end - left

                    if (
                        left >= 0
                        and run_end < n_times
                        and gap_days <= max_gap
                    ):
                        left_value = series[left]
                        right_value = series[run_end]
                        half_gap = _round_output(
                            abs(right_value - left_value) / 2.0
                        )
                        for missing in range(tick, run_end):
                            fraction = (missing - left) / gap_days
                            interpolated = (
                                left_value
                                + (right_value - left_value) * fraction
                            )
                            values[missing][lat_index][lon_index] = (
                                _round_output(interpolated)
                            )
                            status[missing][lat_index][lon_index] = (
                                "interpolated"
                            )
                            uncertainty[missing][lat_index][lon_index] = half_gap
                    else:
                        for missing in range(tick, run_end):
                            status[missing][lat_index][lon_index] = "missing"

                    tick = run_end

        data[element] = {
            "values": values,
            "status": status,
            "uncertainty": uncertainty,
        }

    return {
        "schema": _SCHEMA,
        "times": times,
        "lats": out_lats,
        "lons": out_lons,
        "data": data,
    }

"""Fusion of station observations coming from multiple sources."""

from __future__ import annotations

import math
from typing import Any

_OBSERVATION_KEYS = frozenset(
    {"source", "priority", "id", "lat", "lon", "value", "quality"}
)
_QUALITIES = frozenset({"good", "suspect", "bad"})
_QUALITY_RANK = {"good": 0, "suspect": 1, "bad": 2}


def fuse_observations(observations: list[dict]) -> list[dict]:
    """Fuse multi-source observations, one per station id.

    Records with a ``None`` value or ``bad`` quality are dropped.  The
    remaining records are grouped by ``id``; the first record is chosen by
    quality (``good`` before ``suspect``), then ascending ``priority``, then
    lexicographic ``source``.

    The returned list is sorted by ``id`` and each item uses the key order
    ``id, lat, lon, value, quality, source`` with values taken directly from
    the selected record.

    Raises ``TypeError`` for value-type problems and ``ValueError`` for bad
    key sets, empty strings, duplicate ``(source, id)`` pairs, out-of-range or
    non-finite coordinates, illegal qualities, or conflicting coordinates for
    the same id.
    """
    if not isinstance(observations, list):
        raise TypeError("observations must be a list of observation dicts")

    seen_pairs: set[tuple[str, str]] = set()
    # id -> {"lat": float, "lon": float}
    coordinates: dict[str, dict[str, float]] = {}
    # id -> list of validated records (value not None, quality != "bad")
    groups: dict[str, list[dict]] = {}

    for index, observation in enumerate(observations):
        where = f"observations[{index}]"
        if not isinstance(observation, dict):
            raise TypeError(f"{where} must be a dict")
        if set(observation.keys()) != _OBSERVATION_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys "
                "source, priority, id, lat, lon, value, quality"
            )

        source = observation["source"]
        station_id = observation["id"]
        if not isinstance(source, str):
            raise TypeError(f"{where}.source must be a str")
        if not isinstance(station_id, str):
            raise TypeError(f"{where}.id must be a str")
        if source == "":
            raise ValueError(f"{where}.source must be a non-empty str")
        if station_id == "":
            raise ValueError(f"{where}.id must be a non-empty str")

        pair = (source, station_id)
        if pair in seen_pairs:
            raise ValueError(
                f"duplicate observation (source, id): "
                f"({source!r}, {station_id!r})"
            )
        seen_pairs.add(pair)

        priority = observation["priority"]
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise TypeError(f"{where}.priority must be a non-bool int")

        lat = observation["lat"]
        lon = observation["lon"]
        for name, coord in (("lat", lat), ("lon", lon)):
            if not isinstance(coord, (int, float)) or isinstance(coord, bool):
                raise TypeError(
                    f"{where}.{name} must be a finite non-bool int or float"
                )
            if not math.isfinite(coord):
                raise ValueError(f"{where}.{name} must be finite")
        if not -90.0 <= lat <= 90.0:
            raise ValueError(f"{where}.lat must be within [-90, 90]")
        if not -180.0 <= lon <= 180.0:
            raise ValueError(f"{where}.lon must be within [-180, 180]")

        value = observation["value"]
        if value is not None:
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise TypeError(
                    f"{where}.value must be a number or None"
                )
            if not math.isfinite(value):
                raise ValueError(f"{where}.value must be finite")

        quality = observation["quality"]
        if not isinstance(quality, str):
            raise TypeError(f"{where}.quality must be a str")
        if quality not in _QUALITIES:
            raise ValueError(
                f"{where}.quality must be one of good, suspect, bad"
            )

        previous = coordinates.get(station_id)
        if previous is None:
            coordinates[station_id] = {"lat": lat, "lon": lon}
        elif previous["lat"] != lat or previous["lon"] != lon:
            raise ValueError(
                f"coordinate conflict for id {station_id!r}"
            )

        if value is None or quality == "bad":
            continue
        groups.setdefault(station_id, []).append(observation)

    fused: list[dict] = []
    for station_id in sorted(groups):
        records = groups[station_id]
        selected = min(
            records,
            key=lambda record: (
                _QUALITY_RANK[record["quality"]],
                record["priority"],
                record["source"],
            ),
        )
        fused.append(
            {
                "id": selected["id"],
                "lat": selected["lat"],
                "lon": selected["lon"],
                "value": selected["value"],
                "quality": selected["quality"],
                "source": selected["source"],
            }
        )

    return fused

"""Yearly trend summaries of detected extreme events."""

from __future__ import annotations

import datetime
import math
import re
from typing import Any

_SCHEMA = "climate-grid/trends-v1"
_EXTREMES_SCHEMA = "climate-grid/extremes-v1"
_PERIOD_KEYS = frozenset({"year", "data"})
_EXTREMES_KEYS = frozenset({"schema", "events"})
_EVENT_KEYS = frozenset(
    {"start", "end", "days", "cells", "peak", "mean", "uncertainty"}
)
_METRIC_KEYS = ("count", "days", "cells", "intensity", "uncertainty")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _round_output(value: float) -> float:
    value = round(value, 12)
    if value == 0.0:
        # Normalize negative zero.
        return 0.0
    return value


def _parse_date(value: Any, where: str) -> datetime.date:
    if not isinstance(value, str):
        raise TypeError(f"{where} must be a str")
    if _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{where} must be a YYYY-MM-DD date")
    year, month, day = (int(part) for part in value.split("-"))
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"{where} must be a valid Gregorian date") from None


def _validate_number(value: Any, target: str) -> None:
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        raise TypeError(f"{target} must be a finite non-bool int or float")
    if not math.isfinite(value):
        raise ValueError(f"{target} must be finite")


def _validate_event(event: Any, where: str) -> None:
    if not isinstance(event, dict):
        raise TypeError(f"{where} must be a dict")
    if set(event.keys()) != _EVENT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys "
            "start, end, days, cells, peak, mean, uncertainty"
        )

    start = _parse_date(event["start"], f"{where}.start")
    end = _parse_date(event["end"], f"{where}.end")
    if end < start:
        raise ValueError(f"{where}.end must not be earlier than {where}.start")

    days = event["days"]
    if not isinstance(days, int) or isinstance(days, bool):
        raise TypeError(f"{where}.days must be a non-bool int")
    if days < 1:
        raise ValueError(f"{where}.days must be positive")

    cells = event["cells"]
    if not isinstance(cells, list):
        raise TypeError(f"{where}.cells must be a list")
    if len(cells) == 0:
        raise ValueError(f"{where}.cells must be non-empty")
    previous: tuple[int, int] | None = None
    seen: set[tuple[int, int]] = set()
    for index, cell in enumerate(cells):
        target = f"{where}.cells[{index}]"
        if not isinstance(cell, list):
            raise TypeError(f"{target} must be a list [i, j]")
        if len(cell) != 2:
            raise ValueError(f"{target} must be a two-item list [i, j]")
        for axis, coord in enumerate(cell):
            if not isinstance(coord, int) or isinstance(coord, bool):
                raise TypeError(f"{target}[{axis}] must be a non-bool int")
            if coord < 0:
                raise ValueError(f"{target}[{axis}] must be non-negative")
        i, j = cell
        pair = (i, j)
        if pair in seen:
            raise ValueError(f"{where}.cells must be deduplicated")
        if previous is not None and pair <= previous:
            raise ValueError(f"{where}.cells must be in ascending order")
        seen.add(pair)
        previous = pair

    _validate_number(event["peak"], f"{where}.peak")
    _validate_number(event["mean"], f"{where}.mean")
    _validate_number(event["uncertainty"], f"{where}.uncertainty")


def _validate_detection(detection: Any, where: str) -> None:
    if not isinstance(detection, dict):
        raise TypeError(f"{where} must be a dict")
    if set(detection.keys()) != _EXTREMES_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, events"
        )
    schema = detection["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _EXTREMES_SCHEMA:
        raise ValueError(f"{where}.schema must be {_EXTREMES_SCHEMA!r}")
    events = detection["events"]
    if not isinstance(events, list):
        raise TypeError(f"{where}.events must be a list")
    for index, event in enumerate(events):
        _validate_event(event, f"{where}.events[{index}]")


def _slope(years: list[int], values: list) -> float | None:
    points = [
        (year, value)
        for year, value in zip(years, values)
        if value is not None
    ]
    if len(points) < 2:
        return None
    n = len(points)
    mean_year = sum(year for year, _ in points) / n
    mean_value = sum(value for _, value in points) / n
    denominator = sum((year - mean_year) ** 2 for year, _ in points)
    numerator = sum(
        (year - mean_year) * (value - mean_value)
        for year, value in points
    )
    return _round_output(numerator / denominator)


def summarize(periods) -> dict:
    """Summarize per-element event metrics and their yearly linear trends.

    ``periods`` must be a non-empty list of dicts, each with exactly the
    keys ``year`` and ``data``.  ``year`` is a non-bool int and the years
    must be strictly increasing.  ``data`` is a non-empty dict mapping
    non-empty str element names to complete :func:`climate_grid.extremes.detect`
    results (schema ``climate-grid/extremes-v1``); every year must expose
    the same element keys in the same order.

    For each year and element five yearly metrics are produced: ``count``
    is the number of events, while ``days``, ``cells``, ``intensity`` and
    ``uncertainty`` are the arithmetic means of the events' ``days``,
    ``len(cells)``, ``mean`` and ``uncertainty`` values.  Years without
    events yield a count of ``0`` and ``None`` for the other four metrics.

    Each metric gets an ordinary least-squares slope with the year as x
    in input order.  The ``count`` slope uses every year; the other
    slopes ignore ``None`` points and become ``None`` when fewer than two
    valid points remain.

    The returned mapping uses the key order ``schema, years, data``;
    ``schema`` is ``climate-grid/trends-v1`` and ``years`` preserves the
    input years.  ``data`` follows the first year's element order and each
    element uses the key order ``count, days, cells, intensity,
    uncertainty, slopes``; the first five are per-year lists (``count``
    values are ints) and ``slopes`` is a dict keyed in that same five-key
    order.  Every mean and slope float is ``round(x, 12)`` with negative
    zero normalized to ``0.0``.  Inputs are not modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    if not isinstance(periods, list):
        raise TypeError("periods must be a list")
    if len(periods) == 0:
        raise ValueError("periods must be non-empty")

    years: list[int] = []
    element_order: list[str] | None = None
    yearly_data: list[dict] = []
    for index, period in enumerate(periods):
        where = f"periods[{index}]"
        if not isinstance(period, dict):
            raise TypeError(f"{where} must be a dict")
        if set(period.keys()) != _PERIOD_KEYS:
            raise ValueError(f"{where} must have exactly the keys year, data")

        year = period["year"]
        if not isinstance(year, int) or isinstance(year, bool):
            raise TypeError(f"{where}.year must be a non-bool int")
        if years and year <= years[-1]:
            raise ValueError("periods years must be strictly increasing")

