                    out_uncertainty[t][i][j] = uncertainty[t][i][j]

        result_data[element] = {
            "values": out_values,
            "status": out_status,
            "uncertainty": out_uncertainty,
        }

    return {
        "schema": _SCHEMA,
        "times": times,
        "lats": lats,
        "lons": lons,
        "data": result_data,
    }

